// Herd reminders: Supabase Edge Function "send-reminders".
// GENERATED by "npm run build:function" from src/logic.ts and src/handler.ts.
// Paste this whole file into the Supabase function editor.

import { createClient } from 'npm:@supabase/supabase-js@2';
import webpush from 'npm:web-push@3.6.7';

// ---------------------------------------------------------------------------
// Reminder rules
// ---------------------------------------------------------------------------

// Decides which reminders to send right now. Pure code with no imports, so it
// runs in the Supabase function and in the app's tests alike.
//
// The schedule rules here mirror src/lib/schedule.ts and src/lib/day.ts; a
// test checks that the two agree.

export interface RHousehold {
  id: string;
  name: string;
  timezone: string | null;
}
export interface RMember {
  household_id: string;
  user_id: string;
  notify_late: boolean;
  notify_daily: string | null;
  /** Missing on databases before update 003; treated as on. */
  notify_supplies?: boolean;
}
export interface RPet {
  id: string;
  household_id: string;
  name: string;
}
export interface RRoutine {
  id: string;
  household_id: string;
  pet_id: string;
  title: string;
  kind: 'daily' | 'weekly' | 'monthly' | 'interval' | 'once';
  category: 'care' | 'medication' | 'vaccine' | 'vet';
  dose: string | null;
  times: string[];
  weekdays: number[];
  interval_days: number | null;
  /** Weekly and monthly multiplier. Missing on databases before update 004. */
  repeat_every?: number;
  start_date: string;
  assignee: string | null;
  active: boolean;
}
export interface RLog {
  routine_id: string | null;
  occurrence_date: string;
  slot: string;
  status: 'done' | 'skipped' | 'snoozed';
  snoozed_to: string | null;
}
export interface RSupply {
  id: string;
  household_id: string;
  name: string;
  pet_ids: string[];
  opened_on: string;
  lasts_days: number;
  lead_days: number;
  ordered_on: string | null;
}
export interface ReminderInput {
  households: RHousehold[];
  members: RMember[];
  pets: RPet[];
  routines: RRoutine[];
  logs: RLog[];
  supplies?: RSupply[];
  alreadySent: Set<string>;
}
export interface Reminder {
  userId: string;
  key: string;
  title: string;
  body: string;
  tag: string;
}

/** Minutes after a task's time before anyone is reminded. */
export const LATE_AFTER_MIN = 30;
/** Stop reminding about a late task after this long. */
const LATE_UNTIL_MIN = 180;
/** How long after the chosen time the morning summary can still go out. */
const DAILY_WINDOW_MIN = 15;
/** Reorder reminders go out at 9:00 AM local time. */
export const SUPPLY_AT_MIN = 9 * 60;

const ANY = 'any';

export function daysBetween(a: string, b: string): number {
  const [ay, am, ad] = a.split('-').map(Number);
  const [by, bm, bd] = b.split('-').map(Number);
  return Math.round((Date.UTC(by, bm - 1, bd) - Date.UTC(ay, am - 1, ad)) / 86_400_000);
}

export function addDays(iso: string, n: number): string {
  const [y, m, d] = iso.split('-').map(Number);
  return new Date(Date.UTC(y, m - 1, d + n)).toISOString().slice(0, 10);
}

function weekdayOf(iso: string): number {
  const [y, m, d] = iso.split('-').map(Number);
  return new Date(Date.UTC(y, m - 1, d)).getUTCDay();
}

const toMin = (hhmm: string) => Number(hhmm.slice(0, 2)) * 60 + Number(hhmm.slice(3, 5));

export function formatTime(hhmm: string): string {
  const h = Number(hhmm.slice(0, 2));
  const m = hhmm.slice(3, 5);
  return `${h % 12 === 0 ? 12 : h % 12}:${m} ${h < 12 ? 'AM' : 'PM'}`;
}

export function occurrences(r: RRoutine, date: string): string[] {
  if (!r.active || daysBetween(r.start_date, date) < 0) return [];
  const slots = r.times.length ? [...r.times].sort() : [ANY];
  const every = Math.max(1, r.repeat_every ?? 1);
  switch (r.kind) {
    case 'daily':
      return slots;
    case 'weekly': {
      if (!r.weekdays.includes(weekdayOf(date))) return [];
      if (every === 1) return slots;
      const sunday = (iso: string) => addDays(iso, -weekdayOf(iso));
      const weeks = Math.round(daysBetween(sunday(r.start_date), sunday(date)) / 7);
      return weeks % every === 0 ? slots : [];
    }
    case 'monthly': {
      const [sy, sm, sd] = r.start_date.split('-').map(Number);
      const [y, m, d] = date.split('-').map(Number);
      const months = (y - sy) * 12 + (m - sm);
      if (months < 0 || months % every !== 0) return [];
      const last = new Date(Date.UTC(y, m, 0)).getUTCDate();
      return d === Math.min(sd, last) ? slots : [];
    }
    case 'interval': {
      const n = r.interval_days ?? 0;
      return n >= 1 && daysBetween(r.start_date, date) % n === 0 ? slots : [];
    }
    case 'once':
      return date === r.start_date ? slots : [];
    default:
      // A schedule this code doesn't know yet: skip it rather than stop every reminder.
      return [];
  }
}

/** The local calendar date and minute of the day in a time zone. */
export function localNow(now: Date, timezone: string | null): { date: string; minutes: number } {
  let tz = timezone || 'UTC';
  try {
    new Intl.DateTimeFormat('en-US', { timeZone: tz });
  } catch {
    tz = 'UTC';
  }
  const parts = Object.fromEntries(
    new Intl.DateTimeFormat('en-CA', {
      timeZone: tz,
      year: 'numeric',
      month: '2-digit',
      day: '2-digit',
      hour: '2-digit',
      minute: '2-digit',
      hourCycle: 'h23',
    })
      .formatToParts(now)
      .map((p) => [p.type, p.value]),
  );
  return { date: `${parts.year}-${parts.month}-${parts.day}`, minutes: (Number(parts.hour) % 24) * 60 + Number(parts.minute) };
}

export interface OpenItem {
  routine: RRoutine;
  origDate: string;
  slot: string;
}

/** Tasks still to do on `date` in one household, after skips and snoozes. */
export function openItems(routines: RRoutine[], logs: RLog[], date: string): OpenItem[] {
  const byKey = new Map<string, RLog>();
  for (const l of logs) if (l.routine_id) byKey.set(`${l.routine_id}|${l.occurrence_date}|${l.slot}`, l);
  const byId = new Map(routines.map((r) => [r.id, r]));
  const out: OpenItem[] = [];
  for (const r of routines) {
    for (const slot of occurrences(r, date)) {
      const log = byKey.get(`${r.id}|${date}|${slot}`);
      if (!log || (log.status === 'snoozed' && (!log.snoozed_to || log.snoozed_to === date))) {
        out.push({ routine: r, origDate: date, slot });
      }
    }
  }
  for (const l of logs) {
    if (l.status !== 'snoozed' || l.snoozed_to !== date || l.occurrence_date === date || !l.routine_id) continue;
    const r = byId.get(l.routine_id);
    if (r?.active) out.push({ routine: r, origDate: l.occurrence_date, slot: l.slot });
  }
  return out;
}

/** When a supply runs out, and the day to order more by. */
export function supplyDates(s: RSupply): { runOut: string; orderBy: string } {
  const runOut = addDays(s.opened_on, s.lasts_days);
  return { runOut, orderBy: addDays(runOut, -s.lead_days) };
}

/** Past the order-by date and nobody has ordered more yet. */
export function needsOrder(s: RSupply, date: string): boolean {
  if (s.ordered_on && s.ordered_on >= s.opened_on) return false;
  return date >= supplyDates(s).orderBy;
}

function listWords(items: string[]): string {
  if (items.length <= 1) return items.join('');
  if (items.length === 2) return `${items[0]} and ${items[1]}`;
  return `${items.slice(0, -1).join(', ')} and ${items[items.length - 1]}`;
}

const HEALTH = new Set(['medication', 'vaccine', 'vet']);

export function computeReminders(input: ReminderInput, now: Date): Reminder[] {
  const out: Reminder[] = [];
  const petName = new Map(input.pets.map((p) => [p.id, p.name]));

  for (const h of input.households) {
    const members = input.members.filter((m) => m.household_id === h.id);
    if (!members.length) continue;
    const routines = input.routines.filter((r) => r.household_id === h.id && petName.has(r.pet_id));
    const { date, minutes } = localNow(now, h.timezone);
    const open = openItems(routines, input.logs, date);

    // Late tasks: 30 minutes past their time and still open.
    for (const item of open) {
      if (item.slot === ANY) continue;
      const late = minutes - toMin(item.slot);
      if (late < LATE_AFTER_MIN || late >= LATE_UNTIL_MIN) continue;
      const r = item.routine;
      const assignee = r.assignee ? members.find((m) => m.user_id === r.assignee) : undefined;
      const recipients = (assignee ? [assignee] : members).filter((m) => m.notify_late);
      const pet = petName.get(r.pet_id) ?? 'your pet';
      for (const m of recipients) {
        const key = `late|${r.id}|${item.origDate}|${item.slot}|${m.user_id}`;
        if (input.alreadySent.has(key)) continue;
        const dose = r.category === 'medication' && r.dose ? `${r.dose}, ` : '';
        out.push({
          userId: m.user_id,
          key,
          title: `${r.title} for ${pet} is late`,
          body: `${dose}due at ${formatTime(item.slot)}. Open Herd to check it off or snooze it.`.replace(/^./, (c) => c.toUpperCase()),
          tag: `late-${r.id}-${item.origDate}-${item.slot}`,
        });
      }
    }

    // Time to order more food or supplies: on the order-by day, and again on
    // the last day if nobody has ordered.
    const supplies = (input.supplies ?? []).filter((s) => s.household_id === h.id);
    const toOrder = supplies.filter((s) => needsOrder(s, date));
    const supplyWindow = minutes - SUPPLY_AT_MIN;
    if (supplyWindow >= 0 && supplyWindow < DAILY_WINDOW_MIN) {
      for (const s of toOrder) {
        const { runOut, orderBy } = supplyDates(s);
        const left = daysBetween(date, runOut);
        const lastDay = left === 1;
        if (date !== orderBy && !lastDay) continue;
        const who = s.pet_ids.length ? listWords(s.pet_ids.map((id) => petName.get(id) ?? '').filter(Boolean)) : '';
        for (const m of members) {
          if (m.notify_supplies === false) continue;
          const key = `supply|${s.id}|${s.opened_on}|${date}|${m.user_id}`;
          if (input.alreadySent.has(key)) continue;
          out.push({
            userId: m.user_id,
            key,
            title: lastDay ? `${s.name} runs out tomorrow` : `Time to order more ${s.name}`,
            body: `${left <= 0 ? 'It may already be out' : left === 1 ? 'About 1 day left' : `About ${left} days left`}${
              who ? ` for ${who}` : ''
            }. Tap “I ordered it” in Herd so nobody orders twice.`,
            tag: `supply-${s.id}`,
          });
        }
      }
    }

    // Morning summary at each person's chosen time.
    const tomorrowHealth = openItems(routines, input.logs, addDays(date, 1)).filter((i) => HEALTH.has(i.routine.category));
    for (const m of members) {
      if (!m.notify_daily) continue;
      const since = minutes - toMin(m.notify_daily);
      if (since < 0 || since >= DAILY_WINDOW_MIN) continue;
      const key = `daily|${h.id}|${m.user_id}|${date}`;
      if (input.alreadySent.has(key)) continue;
      if (!open.length && !tomorrowHealth.length && !toOrder.length) continue;
      const pets = [...new Set(open.map((i) => petName.get(i.routine.pet_id) ?? ''))].filter(Boolean);
      const health = open.filter((i) => HEALTH.has(i.routine.category) || i.routine.kind === 'once');
      const parts: string[] = [];
      if (open.length) parts.push(`${open.length} ${open.length === 1 ? 'task' : 'tasks'} for ${listWords(pets)}.`);
      if (health.length) {
        parts.push(`Due today: ${listWords([...new Set(health.map((i) => i.routine.title))])}.`);
      }
      if (tomorrowHealth.length) {
        const t = tomorrowHealth.map((i) => (i.slot === ANY ? i.routine.title : `${i.routine.title} at ${formatTime(i.slot)}`));
        parts.push(`Tomorrow: ${listWords([...new Set(t)])}.`);
      }
      if (toOrder.length) parts.push(`Order soon: ${listWords(toOrder.map((s) => s.name))}.`);
      out.push({ userId: m.user_id, key, title: `Today at ${h.name}`, body: parts.join(' '), tag: `daily-${h.id}` });
    }
  }
  return out;
}

// ---------------------------------------------------------------------------
// Request handler
// ---------------------------------------------------------------------------
// Supabase Edge Function: sends Herd's push reminders. A scheduled job calls
// it every 5 minutes (see supabase/enable-reminders.sql).
//
// It needs no setup of its own: it creates its push keys the first time it
// runs and keeps them in the app_secrets table, which only it can read.


type Sub = { id: string; user_id: string; endpoint: string; p256dh: string; auth: string };

const json = (body: unknown, status = 200) =>
  new Response(JSON.stringify(body), { status, headers: { 'Content-Type': 'application/json' } });

Deno.serve(async (req) => {
  const url = Deno.env.get('SUPABASE_URL');
  const serviceKey = Deno.env.get('SUPABASE_SERVICE_ROLE_KEY');
  if (!url || !serviceKey) return json({ error: 'Missing Supabase settings' }, 500);
  const db = createClient(url, serviceKey, { auth: { persistSession: false } });

  const { data: secretRows, error: secretError } = await db.from('app_secrets').select('key, value');
  if (secretError) return json({ error: secretError.message }, 500);
  const secrets = Object.fromEntries((secretRows ?? []).map((r) => [r.key, r.value]));
  if (!secrets.cron_secret || req.headers.get('x-herd-cron') !== secrets.cron_secret) {
    return json({ error: 'Not allowed' }, 401);
  }

  // Push keys: made once, then reused. The app reads the public half.
  let publicKey = secrets.vapid_public;
  let privateKey = secrets.vapid_private;
  if (!publicKey || !privateKey) {
    const keys = webpush.generateVAPIDKeys();
    const { error } = await db.from('app_secrets').upsert([
      { key: 'vapid_public', value: keys.publicKey },
      { key: 'vapid_private', value: keys.privateKey },
    ]);
    if (error) return json({ error: error.message }, 500);
    publicKey = keys.publicKey;
    privateKey = keys.privateKey;
  }
  webpush.setVapidDetails(secrets.vapid_subject || url, publicKey, privateKey);

  const { data: subs } = await db.from('push_subscriptions').select('id, user_id, endpoint, p256dh, auth');
  const subscriptions = (subs ?? []) as Sub[];
  if (!subscriptions.length) return json({ ok: true, sent: 0, note: 'No phones have reminders turned on yet.' });
  const userIds = [...new Set(subscriptions.map((s) => s.user_id))];

  // select('*') so this keeps working on a database that's missing an update.
  const { data: memberRows } = await db.from('household_members').select('*').in('user_id', userIds);
  const members: RMember[] = (memberRows ?? []).map((m) => ({
    household_id: m.household_id,
    user_id: m.user_id,
    notify_late: m.notify_late ?? true,
    notify_daily: m.notify_daily ?? null,
    notify_supplies: m.notify_supplies ?? true,
  }));
  const householdIds = [...new Set(members.map((m) => m.household_id))];
  if (!householdIds.length) return json({ ok: true, sent: 0 });

  const since = addDays(localNow(new Date(), 'UTC').date, -2);
  const [h, p, r, l, sent, sup] = await Promise.all([
    db.from('households').select('id, name, timezone').in('id', householdIds),
    db.from('pets').select('id, household_id, name').in('household_id', householdIds),
    db.from('routines').select('*').in('household_id', householdIds).eq('active', true),
    db
      .from('task_logs')
      .select('routine_id, occurrence_date, slot, status, snoozed_to')
      .in('household_id', householdIds)
      .not('routine_id', 'is', null)
      .or(`occurrence_date.gte.${since},snoozed_to.gte.${since}`),
    db.from('notifications_sent').select('key').gte('sent_at', new Date(Date.now() - 2 * 86_400_000).toISOString()),
    db
      .from('supplies')
      .select('id, household_id, name, pet_ids, opened_on, lasts_days, lead_days, ordered_on')
      .in('household_id', householdIds),
  ]);
  for (const res of [h, p, r, l, sent]) if (res.error) return json({ error: res.error.message }, 500);

  const reminders = computeReminders(
    {
      households: h.data ?? [],
      members,
      pets: p.data ?? [],
      routines: r.data ?? [],
      logs: (l.data ?? []) as RLog[],
      // No supplies table yet (update 003 not run) just means no reorder reminders.
      supplies: sup.error ? [] : ((sup.data ?? []) as RSupply[]),
      alreadySent: new Set((sent.data ?? []).map((x) => x.key)),
    },
    new Date(),
  );

  let delivered = 0;
  const gone: string[] = [];
  for (const reminder of reminders) {
    const payload = JSON.stringify({ title: reminder.title, body: reminder.body, tag: reminder.tag, url: './' });
    for (const s of subscriptions.filter((x) => x.user_id === reminder.userId)) {
      try {
        await webpush.sendNotification({ endpoint: s.endpoint, keys: { p256dh: s.p256dh, auth: s.auth } }, payload, {
          TTL: 60 * 60,
          urgency: 'high',
        });
        delivered++;
      } catch (e) {
        const code = (e as { statusCode?: number }).statusCode;
        // The phone turned reminders off or the app was removed.
        if (code === 404 || code === 410) gone.push(s.id);
        else console.error('push failed', code, (e as Error).message);
      }
    }
  }

  if (reminders.length) {
    await db.from('notifications_sent').upsert(reminders.map((x) => ({ key: x.key })), { onConflict: 'key', ignoreDuplicates: true });
  }
  if (gone.length) await db.from('push_subscriptions').delete().in('id', gone);
  await db.from('notifications_sent').delete().lt('sent_at', new Date(Date.now() - 3 * 86_400_000).toISOString());

  return json({ ok: true, reminders: reminders.length, delivered, removedPhones: gone.length });
});
